s=s.replace("if(f.size>300000)throw Error('ファイルは300KBまでです。');", "if(f.size>1000000)throw Error('ファイルは1MBまでです。');")
s=s.replace("whatIf='none';go(0);toast('読み込みました。", "whatIf='none';window.WDIntake.resetTransient();go(-1);toast('読み込みました。")
# Keep source provenance metadata when the legacy editors save a task/worker.
s=s.replace("const t={id:form.dataset.id,name:fd.get('name').trim()", "const t={...S.tasks.find(t=>t.id===form.dataset.id),id:form.dataset.id,name:fd.get('name').trim()")
